return ['domain'=>'firmatlas-for-woocommerce','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'FirmAtlas for WooCommerce 0.1.0','pot-creation-date'=>'2026-11-09T13:03:54+00:00','po-revision-date'=>'2026-11-09 14:00+0100','messages'=>['FirmAtlas for WooCommerce'=>'FirmAtlas for WooCommerce','https://github.com/FirmAtlas/firmatlas-for-woocommerce'=>'https://github.com/FirmAtlas/firmatlas-for-woocommerce','Belgian company search at checkout: customers pick their company and the billing details fill themselves. Adds a VAT number field and checks Belgian VAT numbers. Company data from the KBO/BCE through the Firmatlas API.'=>'Belgische bedrijven zoeken bij het afrekenen: klanten kiezen hun bedrijf en de factuurgegevens vullen zich vanzelf in. Voegt een veld voor het btw-nummer toe en controleert Belgische btw-nummers. Bedrijfsgegevens uit de KBO via de Firmatlas-API.','Arne Van Daele'=>'Arne Van Daele','https://arnevandaele.com'=>'https://arnevandaele.com','VAT number'=>'Btw-nummer','VAT number (optional)'=>'Btw-nummer (optioneel)','FirmAtlas: the VAT number %s did not check out (KBO/VIES). Check it before invoicing without VAT.'=>'FirmAtlas: het btw-nummer %s klopt niet volgens de KBO of VIES. Controleer het voor je zonder btw factureert.','valid'=>'geldig','not valid'=>'niet geldig','not checked'=>'niet gecontroleerd','not checked (outside Belgium)'=>'niet gecontroleerd (buiten België)','Enterprise number'=>'Ondernemingsnummer','Settings'=>'Instellingen','Testing…'=>'Bezig met testen…','Not allowed.'=>'Niet toegestaan.','Add and save a secret key first.'=>'Voeg eerst een geheime sleutel toe en sla die op.','The API could not be reached: %s'=>'De API is niet bereikbaar: %s','The API refused the request.'=>'De API weigerde de aanvraag.','Connected. The secret key works.'=>'Verbonden. De geheime sleutel werkt.','Valid VAT number'=>'Geldig btw-nummer','FirmAtlas'=>'FirmAtlas','Company search at checkout'=>'Bedrijven zoeken bij het a